  `exception_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '异常名',
  `exception_message` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '异常导致的消息',
