INSERT  IGNORE INTO `intent_rule` VALUES (1,'crm.rule.overdue-60','逾期60天催收提醒',0,'- id: crm.rule.overdue-60\n  intent: crm.receivable.overdue-warning\n  dataset: crm.overdue-receivable-plans\n  scope:\n    page: [\"crm/receivable\", \"crm/backlog\", \"\"]\n  filter:\n    all:\n      - { op: gte, left: row.overdueDays, right: 60 }\n  badge:\n    text: \"{{count}} 笔回款已逾期超 60 天，需要催收\"\n    level: danger\n  items:\n    limit: 5\n    title: \"第 {{row.period}} 期回款已逾期 {{row.overdueDays}} 天\"\n    subtitle: \"应收 {{row.price | money}} 元\"\n    reason: \"逾期超过 60 天，需要立即推进催收动作\"\n    params:\n      customerId: { from: row.customerId, type: string }\n','逾期超过60天提醒我催收',NULL,'1','2026-09-14 15:48:20','1','2026-09-14 16:37:05',0x01,1),(2,'crm.rule.stagnant-business-45','crm.rule.stagnant-business-45',1,'- id: crm.rule.stagnant-business-45\n  intent: crm.business.advance-strategy\n  dataset: crm.stagnant-businesses\n  scope:\n    page: [\"crm/backlog\", \"crm/business\", \"\"]\n  filter:\n    all:\n      - { op: gte, left: row.daysSinceUpdate, right: 30 }\n  badge:\n    text: \"{{matched}} 个商机已停滞超 45 天\"\n    level: warning\n  items:\n    limit: 5\n    title: \"商机「{{row.name}}」已 {{row.daysSinceUpdate | days}} 天未更新\"\n    subtitle: \"商机金额 {{row.totalPrice | money}} 元\"\n    reason: \"停滞超过 45 天，需要立即推进下一阶段以免丢单\"\n    params:\n      businessId: { from: row.id, type: string }','我负责的商机停滞超过 45 天，提醒我推一把',NULL,'1','2026-09-14 16:13:15','1','2026-09-14 16:13:58',0x01,1),(3,'crm.rule.overdue-60','逾期60天催收提醒',0,'- id: crm.rule.overdue-60\n  intent: crm.receivable.overdue-warning\n  dataset: crm.overdue-receivable-plans\n  scope:\n    page: [\"crm/receivable\", \"crm/backlog\", \"\"]\n  filter:\n    all:\n      - { op: gte, left: row.overdueDays, right: 3 }\n  badge:\n    text: \"{{matched}} 笔回款已逾期，需要催收\"\n    level: danger\n  items:\n    limit: 5\n    title: \"第 {{row.period}} 期回款已逾期 {{row.overdueDays}} 天\"\n    subtitle: \"应收 {{row.price | money}} 元\"\n    reason: \"已经逾期，需要立即推进催收动作\"\n    params:\n      customerId: { from: row.customerId, type: string }\n','逾期超过60天提醒我催收',NULL,'1','2026-09-14 16:37:05','1','2026-09-14 17:22:47',0x01,1),(4,'crm.rule.overdue-60','逾期60天催收提醒',0,'- id: crm.rule.overdue-60\n  intent: crm.receivable.overdue-warning\n  dataset: crm.overdue-receivable-plans\n  scope:\n    page: [\"crm/receivable\", \"crm/backlog\", \"\"]\n  filter:\n    all:\n      - { op: gte, left: row.overdueDays, right: 3 }\n  badge:\n    text: \"{{matched}} 笔回款已逾期，需要催收\"\n    level: danger\n  items:\n    limit: 5\n    title: \"第 {{row.period}} 期回款已逾期 {{row.overdueDays}} 天\"\n    subtitle: \"应收 {{row.price | money}} 元\"\n    reason: \"已经逾期，需要立即推进催收动作\"\n    params:\n      customerId: { from: row.customerId, type: string }\n','逾期超过60天提醒我催收',NULL,'1','2026-09-14 17:22:47','1','2026-09-14 18:07:08',0x01,1),(5,'crm.rule.overdue-60','逾期60天催收提醒',0,'- id: crm.rule.overdue-60\n  intent: crm.receivable.overdue-warning\n  dataset: crm.overdue-receivable-plans\n  scope:\n    page: [\"crm/receivable\", \"crm/backlog\", \"\"]\n  filter:\n    all:\n      - { op: gte, left: row.overdueDays, right: 3 }\n  badge:\n    text: \"{{matched}} 笔回款已逾期，需要催收\"\n    level: danger\n  items:\n    limit: 5\n    title: \"第 {{row.period}} 期回款已逾期 {{row.overdueDays}} 天\"\n    subtitle: \"应收 {{row.price | money}} 元\"\n    reason: \"已经逾期，需要立即推进催收动作\"\n    params:\n      customerId: { from: row.customerId, type: string }\n','逾期超过60天提醒我催收',NULL,'1','2026-09-14 18:07:09','1','2026-09-14 18:32:46',0x01,1),(6,'crm.rule.overdue-60','逾期60天催收提醒',0,'- id: crm.rule.overdue-60\n  intent: crm.receivable.overdue-warning\n  dataset: crm.overdue-receivable-plans\n  scope:\n    page: [\"crm/receivable\", \"crm/backlog\", \"\"]\n  filter:\n    all:\n      - { op: gte, left: row.overdueDays, right: 3 }\n  badge:\n    text: \"{{matched}} 笔回款已逾期，需要催收\"\n    level: danger\n  items:\n    limit: 5\n    title: \"第 {{row.period}} 期回款已逾期 {{row.overdueDays}} 天\"\n    subtitle: \"应收 {{row.price | money}} 元\"\n    reason: \"已经逾期，需要立即推进催收动作\"\n    params:\n      customerId: { from: row.customerId, type: string }\n','逾期超过60天提醒我催收',NULL,'1','2026-09-14 18:32:46','1','2026-09-14 19:09:29',0x01,1),(7,'crm.rule.overdue-60','逾期60天催收提醒',0,'- id: crm.rule.overdue-60\n  intent: crm.receivable.overdue-warning\n  dataset: crm.overdue-receivable-plans\n  scope:\n    page: [\"crm/receivable\", \"crm/backlog\", \"\"]\n  filter:\n    all:\n      - { op: gte, left: row.overdueDays, right: 3 }\n  badge:\n    text: \"{{matched}} 笔回款已逾期，需要催收\"\n    level: danger\n  items:\n    limit: 5\n    title: \"第 {{row.period}} 期回款已逾期 {{row.overdueDays}} 天\"\n    subtitle: \"应收 {{row.price | money}} 元\"\n    reason: \"已经逾期，需要立即推进催收动作\"\n    params:\n      customerId: { from: row.customerId, type: string }\n','逾期超过60天提醒我催收',NULL,'1','2026-09-14 19:09:29','1','2026-09-14 19:09:29',0x00,1);
