INSERT  IGNORE INTO `intent_spec` VALUES (8,'poc.customer.health-score','{\"id\":\"poc.customer.health-score\",\"name\":\"客户健康度评分（增强版）\",\"description\":\"综合客户活跃度、成交与跟进节奏输出健康度评分与改善建议\",\"version\":1,\"scope\":\"LOCAL\",\"paramsSchema\":{\"type\":\"object\",\"properties\":{\"customerId\":{\"type\":\"string\",\"title\":\"客户编号\"}},\"required\":[\"customerId\"]},\"context\":[],\"outputSchema\":{\"type\":\"object\",\"required\":[\"title\",\"summary\",\"blocks\"],\"properties\":{\"followups\":{\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"summary\":{\"type\":\"string\"},\"blocks\":{\"items\":{\"type\":\"object\",\"required\":[\"kind\"],\"properties\":{\"rows\":{\"items\":{\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"type\":\"array\"},\"columns\":{\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"kind\":{\"enum\":[\"text\",\"kv\",\"table\",\"list\",\"badges\"],\"type\":\"string\"},\"title\":{\"type\":\"string\"},\"text\":{\"type\":\"string\"},\"items\":{\"items\":{\"type\":\"object\",\"required\":[\"label\",\"value\"],\"properties\":{\"label\":{\"type\":\"string\"},\"value\":{\"type\":\"string\"}}},\"type\":\"array\"},\"level\":{\"enum\":[\"info\",\"warning\",\"danger\"],\"type\":\"string\"}}},\"type\":\"array\"},\"nextIntents\":{\"type\":\"array\",\"description\":\"推荐的下一步意图（intentId 必须来自意图目录）\",\"items\":{\"type\":\"object\",\"required\":[\"intentId\",\"title\"],\"properties\":{\"title\":{\"type\":\"string\"},\"reason\":{\"type\":\"string\"},\"params\":{\"type\":\"object\"},\"intentId\":{\"type\":\"string\"}}}},\"title\":{\"type\":\"string\"}}},\"cardType\":\"analysis\",\"tools\":[\"crm_get_customer\",\"crm_list_follow_ups\"],\"pages\":[\"crm/customer\"],\"promptTemplate\":\"你是客户成功分析师。基于客户数据输出健康度评分（0-100）、评分依据与 3 条改善建议，禁止编造数据。\\n\",\"policy\":{}}','custom',NULL,'1','2026-09-12 00:02:36','1','2026-09-12 00:05:51',0x01,0),(9,'poc.intent.crud-check','{\"id\":\"poc.intent.crud-check\",\"name\":\"CRUD 验证意图\",\"description\":\"一句话描述这个意图做什么\",\"version\":1,\"scope\":\"LOCAL\",\"paramsSchema\":{\"type\":\"object\",\"properties\":{\"customerId\":{\"type\":\"string\",\"title\":\"客户编号\"}},\"required\":[\"customerId\"]},\"context\":[{\"key\":\"page\",\"title\":\"来源页面\",\"required\":false}],\"outputSchema\":{\"properties\":{\"title\":{\"type\":\"string\"},\"followups\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"summary\":{\"type\":\"string\"},\"blocks\":{\"type\":\"array\",\"items\":{\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"text\",\"kv\",\"table\",\"list\",\"badges\"]},\"title\":{\"type\":\"string\"},\"text\":{\"type\":\"string\"},\"items\":{\"type\":\"array\",\"items\":{\"properties\":{\"label\":{\"type\":\"string\"},\"value\":{\"type\":\"string\"}},\"type\":\"object\",\"required\":[\"label\",\"value\"]}},\"level\":{\"type\":\"string\",\"enum\":[\"info\",\"warning\",\"danger\"]},\"rows\":{\"type\":\"array\",\"items\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}},\"columns\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}},\"type\":\"object\",\"required\":[\"kind\"]}},\"nextIntents\":{\"type\":\"array\",\"description\":\"推荐的下一步意图（intentId 必须来自意图目录）\",\"items\":{\"properties\":{\"reason\":{\"type\":\"string\"},\"params\":{\"type\":\"object\"},\"intentId\":{\"type\":\"string\"},\"title\":{\"type\":\"string\"}},\"type\":\"object\",\"required\":[\"intentId\",\"title\"]}}},\"type\":\"object\",\"required\":[\"title\",\"summary\",\"blocks\"]},\"cardType\":\"analysis\",\"tools\":[],\"pages\":[\"crm/customer\"],\"promptTemplate\":\"你是 XX 领域的智能助理。基于工具返回的数据完成任务，禁止编造。\\n\",\"policy\":{}}','custom',NULL,'1','2026-09-12 00:46:26','1','2026-09-12 00:49:40',0x01,0),(10,'poc.ui.crud-check','{\"id\":\"poc.ui.crud-check\",\"name\":\"UI CRUD 验证\",\"description\":\"一句话描述这个意图做什么\",\"version\":1,\"scope\":\"LOCAL\",\"paramsSchema\":{\"type\":\"object\",\"properties\":{\"customerId\":{\"type\":\"string\",\"title\":\"客户编号\"}},\"required\":[\"customerId\"]},\"context\":[{\"key\":\"page\",\"title\":\"来源页面\",\"required\":false}],\"outputSchema\":{\"properties\":{\"title\":{\"type\":\"string\"},\"followups\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"summary\":{\"type\":\"string\"},\"blocks\":{\"type\":\"array\",\"items\":{\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"text\",\"kv\",\"table\",\"list\",\"badges\"]},\"title\":{\"type\":\"string\"},\"text\":{\"type\":\"string\"},\"items\":{\"type\":\"array\",\"items\":{\"properties\":{\"label\":{\"type\":\"string\"},\"value\":{\"type\":\"string\"}},\"type\":\"object\",\"required\":[\"label\",\"value\"]}},\"level\":{\"type\":\"string\",\"enum\":[\"info\",\"warning\",\"danger\"]},\"rows\":{\"type\":\"array\",\"items\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}},\"columns\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}},\"type\":\"object\",\"required\":[\"kind\"]}},\"nextIntents\":{\"type\":\"array\",\"description\":\"推荐的下一步意图（intentId 必须来自意图目录）\",\"items\":{\"properties\":{\"reason\":{\"type\":\"string\"},\"params\":{\"type\":\"object\"},\"intentId\":{\"type\":\"string\"},\"title\":{\"type\":\"string\"}},\"type\":\"object\",\"required\":[\"intentId\",\"title\"]}}},\"type\":\"object\",\"required\":[\"title\",\"summary\",\"blocks\"]},\"cardType\":\"analysis\",\"tools\":[],\"pages\":[\"crm/customer\"],\"promptTemplate\":\"你是 XX 领域的智能助理。基于工具返回的数据完成任务，禁止编造。\\n\",\"policy\":{}}','custom',NULL,'1','2026-09-12 01:55:55','1','2026-09-12 01:56:27',0x01,0),(46,'crm.backlog.today-priority','{\"id\":\"crm.backlog.today-priority\",\"name\":\"今日跟进优先级\",\"description\":\"结合我负责的待办事实，排出今天先做的 5 件事与理由\",\"aliases\":[\"今天该做什么\",\"今天先干什么\",\"今日待办\",\"我今天的活\"],\"version\":1,\"scope\":\"LOCAL\",\"paramsSchema\":{\"type\":\"object\",\"properties\":{},\"required\":[]},\"context\":[{\"key\":\"page\",\"title\":\"来源页面\",\"required\":false}],\"outputSchema\":{\"properties\":{\"title\":{\"type\":\"string\"},\"followups\":{\"type\":\"array\",\"description\":\"本次结果里还需要用户跟进/核实的具体事项（3~5 条，每条一句话；无则留空）\",\"items\":{\"type\":\"string\"}},\"summary\":{\"type\":\"string\"},\"blocks\":{\"items\":{\"properties\":{\"kind\":{\"enum\":[\"text\",\"kv\",\"table\",\"list\",\"badges\"],\"type\":\"string\"},\"title\":{\"type\":\"string\"},\"text\":{\"type\":\"string\"},\"items\":{\"items\":{\"properties\":{\"label\":{\"type\":\"string\"},\"value\":{\"type\":\"string\"}},\"type\":\"object\",\"required\":[\"label\",\"value\"]},\"type\":\"array\"},\"level\":{\"enum\":[\"info\",\"warning\",\"danger\"],\"type\":\"string\"},\"rows\":{\"items\":{\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"type\":\"array\"},\"columns\":{\"items\":{\"type\":\"string\"},\"type\":\"array\"}},\"type\":\"object\",\"required\":[\"kind\"]},\"type\":\"array\"},\"nextIntents\":{\"type\":\"array\",\"description\":\"推荐的下一步意图（intentId 必须来自意图目录）\",\"items\":{\"properties\":{\"params\":{\"type\":\"object\"},\"intentId\":{\"type\":\"string\"},\"title\":{\"type\":\"string\"},\"reason\":{\"type\":\"string\"}},\"type\":\"object\",\"required\":[\"intentId\",\"title\"]}}},\"type\":\"object\",\"required\":[\"title\",\"summary\",\"blocks\"]},\"cardType\":\"plan\",\"tools\":[\"crm_backlog_facts\",\"crm_list_clues\",\"crm_customer_facts\"],\"pages\":[\"crm/backlog\"],\"promptTemplate\":\"你是 CRM 销售助理，负责帮销售决定\\\"今天先干什么\\\"。\\n按顺序执行：\\n1. 调用 crm_backlog_facts 读取我今天的事实（今日需联系客户、待跟进客户/线索、合同待审核、\\n   合同即将到期、回款待审核、回款计划逾期、客户待进公馆）；\\n2. 若\\\"客户待跟进\\\"大于 0，调用 crm_customer_facts 了解其中最重要的 1~2 个客户（可选，最多 2 次）；\\n3. 按\\\"影响金额 > 时间紧迫度 > 动作成本\\\"排序，给出**今天先做的 5 件事**。\\n输出要求：\\n- 每件事一行：对象名称 + 一个具体动作 + 为什么现在做（必须引用事实数字，如\\\"已逾期 18 天\\\"\\\"还有 3 天到期\\\"）+ 预计耗时；\\n- 所有数字必须来自工具返回，禁止编造；为 0 的类别不要出现在清单里；\\n- 若今天确实没有待办，明确说\\\"今天没有到期事项\\\"，并给一条主动经营建议。\\n\",\"policy\":{\"timeoutSeconds\":180}}','builtin','classpath 种子',NULL,'2026-09-14 15:34:32',NULL,'2026-09-14 15:34:32',0x00,0),(47,'crm.backlog.weekly-review','{\"id\":\"crm.backlog.weekly-review\",\"name\":\"本周跟进复盘\",\"description\":\"本周跟进覆盖、推进的商机、风险客户与下周重点\",\"aliases\":[\"本周干得怎么样\",\"这周跟进复盘\",\"一周总结\",\"本周总结\"],\"version\":1,\"scope\":\"LOCAL\",\"paramsSchema\":{\"type\":\"object\",\"properties\":{},\"required\":[]},\"context\":[{\"key\":\"page\",\"title\":\"来源页面\",\"required\":false}],\"outputSchema\":{\"properties\":{\"title\":{\"type\":\"string\"},\"followups\":{\"type\":\"array\",\"description\":\"本次结果里还需要用户跟进/核实的具体事项（3~5 条，每条一句话；无则留空）\",\"items\":{\"type\":\"string\"}},\"summary\":{\"type\":\"string\"},\"blocks\":{\"items\":{\"properties\":{\"kind\":{\"enum\":[\"text\",\"kv\",\"table\",\"list\",\"badges\"],\"type\":\"string\"},\"title\":{\"type\":\"string\"},\"text\":{\"type\":\"string\"},\"items\":{\"items\":{\"properties\":{\"label\":{\"type\":\"string\"},\"value\":{\"type\":\"string\"}},\"type\":\"object\",\"required\":[\"label\",\"value\"]},\"type\":\"array\"},\"level\":{\"enum\":[\"info\",\"warning\",\"danger\"],\"type\":\"string\"},\"rows\":{\"items\":{\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"type\":\"array\"},\"columns\":{\"items\":{\"type\":\"string\"},\"type\":\"array\"}},\"type\":\"object\",\"required\":[\"kind\"]},\"type\":\"array\"},\"nextIntents\":{\"type\":\"array\",\"description\":\"推荐的下一步意图（intentId 必须来自意图目录）\",\"items\":{\"properties\":{\"params\":{\"type\":\"object\"},\"intentId\":{\"type\":\"string\"},\"title\":{\"type\":\"string\"},\"reason\":{\"type\":\"string\"}},\"type\":\"object\",\"required\":[\"intentId\",\"title\"]}}},\"type\":\"object\",\"required\":[\"title\",\"summary\",\"blocks\"]},\"cardType\":\"analysis\",\"tools\":[\"crm_backlog_facts\",\"crm_stats_rank\",\"crm_list_clues\",\"crm_list_receivable_plans\"],\"pages\":[\"crm/backlog\"],\"promptTemplate\":\"你是 CRM 销售主管，帮销售做本周复盘。\\n1. 调用 crm_backlog_facts 取当前待办全貌；\\n2. 调用 crm_stats_rank（dimension=followCount）看跟进次数分布，判断投入是否集中在大客户上；\\n3. 调用 crm_list_receivable_plans（remindType=2）取逾期回款计划。\\n输出四段：\\n① 本周进展（用数字：待跟进/待审核/逾期各多少）；\\n② 推进中的商机与卡点；\\n③ 风险客户清单（逾期回款 + 长期未联系）；\\n④ 下周 3 个重点动作。\\n所有数字必须来自工具返回；没有数据支撑的结论不要写。\\n\",\"policy\":{\"timeoutSeconds\":180}}','builtin','classpath 种子',NULL,